INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist eine Testdokumentation immer notwendig?', 2, '[{"text": "Ja", "correct": true, "because": "Erforderlich für Nachvollziehbarkeit"}, {"text": "Nein", "correct": false, "because": "Selten entbehrlich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Element priorisiere ich in einem Testplan?', 3, '[{"text": "Testziele", "correct": true, "because": "Definiert den Zweck"}, {"text": "Farbliche Gestaltung", "correct": false, "because": "Irrelevant"}, {"text": "Budgetdetails", "correct": false, "because": "Sekundär"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Eigenschaften machen eine Testdokumentation effektiv?', 5, '[{"text": "Klarheit", "correct": true, "because": "Ermöglicht Verständnis"}, {"text": "Vollständigkeit", "correct": true, "because": "Alle Tests abdecken"}, {"text": "Minimaler Umfang", "correct": false, "because": "Detailtiefe nötig"}, {"text": "Schöne Optik", "correct": false, "because": "Technisch irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Testpläne definieren Testfälle. b) Ergebnisse sind nur für Entwickler wichtig.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, auch für andere relevant"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Erstellung eines Testplans?', 4, '[{"text": "Testumfang", "correct": false, "because": "Definiert Abdeckung"}, {"text": "Testmethoden", "correct": false, "because": "Wichtig für Durchführung"}, {"text": "Design der Vorlage", "correct": true, "because": "Technisch irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Testergebnisse ohne Testplan sinnvoll sind?', 2, '[{"text": "Nein", "correct": true, "because": "Kontext fehlt ohne Plan"}, {"text": "Ja", "correct": false, "because": "Schwer nachvollziehbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Feature priorisiere ich bei der Dokumentation von Testergebnissen?', 3, '[{"text": "Genauigkeit", "correct": true, "because": "Zuverlässige Daten"}, {"text": "Schnelle Erstellung", "correct": false, "because": "Qualität zählt"}, {"text": "Visuelle Gestaltung", "correct": false, "because": "Sekundär"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet ein Testplan?', 5, '[{"text": "Strukturierte Tests", "correct": true, "because": "Klarer Ablauf"}, {"text": "Nachvollziehbarkeit", "correct": true, "because": "Dokumentiert Vorgehen"}, {"text": "Geringer Aufwand", "correct": false, "because": "Erstellung kostet Zeit"}, {"text": "Schönes Layout", "correct": false, "because": "Nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Testpläne sind für alle Tests gleich. b) Ergebnisse müssen detailliert sein. Stimmt das?', 3, '[{"text": "Nur b) stimmt", "correct": true, "because": "a) ist falsch, Pläne variieren"}, {"text": "Beides stimmt", "correct": false, "because": "a) ist falsch"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "b) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für eine Testdokumentation?', 4, '[{"text": "Testfälle", "correct": false, "because": "Kern des Plans"}, {"text": "Ergebnisse", "correct": false, "because": "Zeigen Teststatus"}, {"text": "Dekorative Grafiken", "correct": true, "because": "Technisch irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Sind Testpläne nur für große Projekte?', 2, '[{"text": "Nein", "correct": true, "because": "Auch kleine profitieren"}, {"text": "Ja", "correct": false, "because": "Nicht größenabhängig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren sind für Testergebnisse entscheidend?', 4, '[{"text": "Fehlerbeschreibung", "correct": true, "because": "Hilft bei Nachbesserung"}, {"text": "Erfolgsquote", "correct": true, "because": "Zeigt Teststatus"}, {"text": "Minimale Details", "correct": false, "because": "Detailliertheit nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Testergebnisse ohne Plan nutzlos sind. Stimmt das?', 2, '[{"text": "Ja", "correct": true, "because": "Ohne Kontext schwer interpretierbar"}, {"text": "Nein", "correct": false, "because": "Können teilweise nützlich sein"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich in einem Testplan für eine Web-App?', 3, '[{"text": "Testabdeckung", "correct": true, "because": "Alle Funktionen prüfen"}, {"text": "Schnelle Fertigstellung", "correct": false, "because": "Qualität zählt"}, {"text": "Visuelle Gestaltung", "correct": false, "because": "Sekundär"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Testpläne enthalten Testmethoden. b) Ergebnisse sind nur für Manager.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, für alle relevant"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Nachteile hat eine unvollständige Testdokumentation?', 5, '[{"text": "Fehlende Nachvollziehbarkeit", "correct": true, "because": "Tests schwer überprüfbar"}, {"text": "Schwierige Fehleranalyse", "correct": true, "because": "Daten fehlen"}, {"text": "Schnelle Erstellung", "correct": false, "because": "Nicht vorteilhaft"}, {"text": "Hohe Übersichtlichkeit", "correct": false, "because": "Eher verwirrend"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei Testergebnissen für einen Server unwichtig?', 3, '[{"text": "Fehlermeldungen", "correct": false, "because": "Wichtig für Analyse"}, {"text": "Testdurchführung", "correct": false, "because": "Kontext nötig"}, {"text": "Optisches Design", "correct": true, "because": "Technisch irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Müssen Testpläne ständig aktualisiert werden?', 3, '[{"text": "Ja", "correct": true, "because": "Änderungen im System berücksichtigen"}, {"text": "Nein", "correct": false, "because": "Aktualität wichtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Ergebnisse ohne Testplan ausreichen?', 2, '[{"text": "Nein", "correct": true, "because": "Ohne Plan fehlt Ziel"}, {"text": "Ja", "correct": false, "because": "Kontext entscheidend"}]'),
('00000000-0000-0000-0000-000000000000', 'Welchen Plan wähle ich für eine umfassende Testdokumentation?', 4, '[{"text": "Detaillierter Testplan", "correct": true, "because": "Alles abdecken"}, {"text": "Kurzer Überblick", "correct": false, "because": "Zu oberflächlich"}, {"text": "Keine Dokumentation", "correct": false, "because": "Unzureichend"}]');
